	/**
	 * One open dependency partition. At most one chunk task touches it at a time, so its cursor, lookup cache and run
	 * output are handed between the coordinator and one worker without further locking.
	 */
	private static final class DependencyPartition implements AutoCloseable {
		private final int partition;
		private final PartitionValueDictionary.PartitionReader reader;
		private final DependencyBucketCursor cursor;
		private final Path runPath;
		private final LookupCache cache;
		private DataOutputStream output;
		private long rows;
		private long previousOwner = -1L;
		private int previousComponent = -1;
		private boolean inFlight;
		private boolean closed;

		private DependencyPartition(int partition, PartitionValueDictionary.PartitionReader reader,
				DependencyBucketCursor cursor, Path runPath, DataOutputStream output, LookupCache cache) {
			this.partition = partition;
			this.reader = reader;
			this.cursor = cursor;
			this.runPath = runPath;
			this.output = output;
			this.cache = cache;
		}

		/** Runs on the worker: streams up to one chunk of records through the dictionary into the run output. */
		private DependencyChunkOutcome resolveChunk(long workBytes, long recordAllowanceBytes, int maxRecords,
				LmdbStoreFormat config, BooleanSupplier cancellationSignal) throws IOException {
			long chunkRows = 0L;
			long retained = 0L;
			boolean exhausted = false;
			while (chunkRows < maxRecords) {
				checkCancelled(cancellationSignal);
				long nextBytes = cursor.peekNextRecordRetainedBytes();
				if (nextBytes < 0L) {
					exhausted = true;
					break;
				}
				// The task reserved memory for one record of at most recordAllowanceBytes; a larger record starts a
				// new chunk whose reservation covers it.
				if (chunkRows > 0L && nextBytes > recordAllowanceBytes) {
					break;
				}
				DependencyRecord record = cursor.next();
				if (record.owner() < previousOwner
						|| record.owner() == previousOwner && record.component() <= previousComponent) {
					throw new IOException("Value dependency bucket is not ordered by owner and component");
				}
				previousOwner = record.owner();
				previousComponent = record.component();
				long id = lookup(record, config);
				output.writeLong(record.owner());
				output.writeLong(record.component());
				output.writeLong(id);
				chunkRows++;
				retained = Math.addExact(retained, nextBytes);
				if (retained >= workBytes) {
					break;
				}
			}
			rows = Math.addExact(rows, chunkRows);
			return new DependencyChunkOutcome(chunkRows, retained, exhausted);
		}

		private long lookup(DependencyRecord record, LmdbStoreFormat config) throws IOException {
			if (!CanonicalTermCodec.isNamespace(record.key())) {
				long inlineId = InlineValueCodec.tryEncode(CanonicalTermCodec.decode(record.key()), config);
				if (inlineId != 0L) {
					return inlineId;
				}
			}
			long id = cache.lookup(record.routeHash(), record.key());
			if (id == 0L) {
				id = reader.lookup(record.key());
				if (id == 0L) {
					throw new IOException("Missing value-ID dependency for assigned value " + record.owner()
							+ " component " + record.component());
				}
				cache.put(record.routeHash(), record.key(), id);
			}
			return id;
		}

		/** Ends the run output; returns its size in bytes. */
		private long finishOutput() throws IOException {
			DataOutputStream finishing = output;
			output = null;
			if (finishing != null) {
				finishing.close();
			}
			return Files.size(runPath);
		}

		@Override
		public void close() throws IOException {
			if (closed) {
				return;
			}
			closed = true;
			IOException failure = null;
			if (output != null) {
				try {
					output.close();
				} catch (IOException closeFailure) {
					failure = closeFailure;
				}
				output = null;
			}
			try {
				cursor.close();
			} catch (IOException closeFailure) {
				if (failure == null) {
					failure = closeFailure;
				} else {
					failure.addSuppressed(closeFailure);
				}
			}
			try {
				reader.close();
			} catch (RuntimeException closeFailure) {
				IOException wrapped = new IOException(
						"Could not close value dictionary reader for partition " + partition, closeFailure);
				if (failure == null) {
					failure = wrapped;
				} else {
					failure.addSuppressed(wrapped);
				}
			}
			if (failure != null) {
				throw failure;
			}
		}
	}

